def degreeOneHomotopyComponents (h : ∀ n, C.X n ⟶ D.X (n + 1))
    (i j : ℕ) : C.X i ⟶ D.X j :=
  if w : i + 1 = j then h i ≫ eqToHom (congrArg D.X w) else 0

